<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { enterpriseVerificationApi } from '../api/admin'
const rows=ref<any[]>([]); const status=ref('pending'); const error=ref(''); const loading=ref(true); const note=ref<Record<string,string>>({})
async function load(){loading.value=true;try{rows.value=(await enterpriseVerificationApi.list(status.value)).data.data}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}}
async function review(id:string,approved:boolean){try{await enterpriseVerificationApi.review(id,approved,note.value[id]||'');await load()}catch(e:any){error.value=e.response?.data?.detail||e.message}}
onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">ENTERPRISE REVIEW</span><h2>企业认证审核</h2><p>审核客户提交的企业资料，审核通过后转为企业客户。</p></div><select v-model="status" @change="load"><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已拒绝</option><option value="all">全部</option></select></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取认证申请…</div><div v-else class="module-table-wrap customer-management-table"><table class="admin-table"><thead><tr><th>企业名称</th><th>统一社会信用代码</th><th>法定代表人</th><th>联系电话</th><th>状态</th><th>审核意见</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.company_name}}</td><td>{{row.registration_no||'—'}}</td><td>{{row.legal_representative||'—'}}</td><td>{{row.contact_phone||'—'}}</td><td>{{row.status}}</td><td><input v-model="note[row.id]" placeholder="填写审核意见" /></td><td><button v-if="row.status==='pending'" class="table-action" @click="review(row.id,true)">通过</button><button v-if="row.status==='pending'" class="table-action danger" @click="review(row.id,false)">拒绝</button></td></tr><tr v-if="!rows.length"><td colspan="7" class="table-empty">暂无认证申请</td></tr></tbody></table></div></section></template>